import React from 'react';
import styles from './PageFilter.module.css';

const SORT_OPTIONS = [
  { value: 'featured', label: 'Featured' },
  { value: 'price-low', label: 'Price: Low to High' },
  { value: 'price-high', label: 'Price: High to Low' },
  { value: 'rating', label: 'Highest Rated' },
  { value: 'newest', label: 'Newest' },
];

const RATING_OPTIONS = [0, 4.5, 4.6, 4.7, 4.8, 4.9];

const PageFilter = ({
  sortBy,
  setSortBy,
  priceRange,
  setPriceRange,
  ratingFilter,
  setRatingFilter,
  categories,
  selectedCategory,
  setSelectedCategory,
  showRating = true,
}) => {
  return (
    <aside className={styles.sidebar}>
      <div className={styles.filterGroup}>
        <h3 className={styles.filterTitle}>Sort By</h3>
        <select
          value={sortBy}
          onChange={(e) => setSortBy(e.target.value)}
          className={styles.select}
        >
          {SORT_OPTIONS.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      </div>

      <div className={styles.filterGroup}>
        <h3 className={styles.filterTitle}>Price Range</h3>
        <div className={styles.priceRange}>
          <input
            type="number"
            min="0"
            max="50000"
            value={priceRange[0]}
            onChange={(e) =>
              setPriceRange([Number(e.target.value) || 0, priceRange[1]])
            }
            className={styles.priceInput}
            placeholder="Min"
          />
          <span className={styles.priceSep}>—</span>
          <input
            type="number"
            min="0"
            max="50000"
            value={priceRange[1]}
            onChange={(e) =>
              setPriceRange([priceRange[0], Number(e.target.value) || 50000])
            }
            className={styles.priceInput}
            placeholder="Max"
          />
        </div>
      </div>

      {categories && categories.length > 0 && setSelectedCategory && (
        <div className={styles.filterGroup}>
          <h3 className={styles.filterTitle}>Category</h3>
          <div className={styles.categoryList}>
            <button
              className={`${styles.catBtn} ${
                selectedCategory === 'All' ? styles.catBtnActive : ''
              }`}
              onClick={() => setSelectedCategory('All')}
            >
              All
            </button>
            {categories.map((cat) => {
              const name = cat.name ?? cat;
              return (
                <button
                  key={name}
                  className={`${styles.catBtn} ${
                    selectedCategory === name ? styles.catBtnActive : ''
                  }`}
                  onClick={() => setSelectedCategory(name)}
                >
                  {name}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {showRating && (
        <div className={styles.filterGroup}>
          <h3 className={styles.filterTitle}>Rating</h3>
          <div className={styles.ratingList}>
            {RATING_OPTIONS.map((r) => (
              <label key={r} className={styles.ratingLabel}>
                <input
                  type="radio"
                  name="pf-rating"
                  value={r}
                  checked={ratingFilter === r}
                  onChange={() => setRatingFilter(r)}
                />
                {r === 0 ? 'All Ratings' : `${r}★ & Up`}
              </label>
            ))}
          </div>
        </div>
      )}
    </aside>
  );
};

export default PageFilter;
